New-Item -ItemType Directory -Path $taskPhase11 -Force | Out-Null
Copy-Item -LiteralPath 'plan/bc-closed-loop-20261012/first-stage-plan-v1.md' -Destination $taskPhase11
Copy-Item -LiteralPath 'plan/bc-closed-loop-20261012/first-stage-plan-v2.md' -Destination $taskPhase11
$taskPhase12=Join-Path $taskArchive 'stages/12-final-delivery'
foreach($taskRel in $taskCurrent){
 $taskDest=Join-Path $taskPhase12 $taskRel
 New-Item -ItemType Directory -Path (Split-Path $taskDest -Parent) -Force | Out-Null
 Copy-Item -LiteralPath (Join-Path $taskRoot $taskRel) -Destination $taskDest
}
$taskAllFiles=@(foreach($taskFolder in $taskFolders){Get-ChildItem -LiteralPath $taskFolder -Recurse -File})
$taskMan=@(foreach($taskFile in $taskAllFiles){
 $taskRel=[IO.Path]::GetRelativePath($taskRoot,$taskFile.FullName).Replace('\','/')
 [pscustomobject]@{path=$taskRel;active=($taskRel -in $taskCurrent);bytes=$taskFile.Length;sha256=(Get-FileHash -LiteralPath $taskFile.FullName -Algorithm SHA256).Hash.ToLower()}
})
$taskMan | Sort-Object path | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $taskArchive 'deliverables-manifest.json') -Encoding utf8

$taskDiffDir=Join-Path $taskArchive 'diffs'
New-Item -ItemType Directory -Path $taskDiffDir -Force | Out-Null
$taskGroups=@{}
foreach($taskFile in $taskAllFiles){
 if($taskFile.Name -match '^(.*)-v(\d+)\.md$'){
  $taskKey=Join-Path $taskFile.DirectoryName $Matches[1]
  if(-not $taskGroups.ContainsKey($taskKey)){$taskGroups[$taskKey]=[Collections.Generic.List[object]]::new()}
  $taskGroups[$taskKey].Add([pscustomobject]@{file=$taskFile;version=[int]$Matches[2]})
 }
}
$taskDiffIndex=@(foreach($taskKey in ($taskGroups.Keys | Sort-Object)){
 $taskVersions=@($taskGroups[$taskKey] | Sort-Object version)
 for($taskI=1;$taskI -lt $taskVersions.Count;$taskI++){
  $taskFrom=$taskVersions[$taskI-1].file.FullName
  $taskTo=$taskVersions[$taskI].file.FullName
  $taskFromRel=[IO.Path]::GetRelativePath($taskRoot,$taskFrom).Replace('\','/')
  $taskToRel=[IO.Path]::GetRelativePath($taskRoot,$taskTo).Replace('\','/')
  $taskDiffName=($taskFromRel -replace '/','--')+'--to-v'+$taskVersions[$taskI].version+'.patch'
  $taskDiffOut=@(& git -c core.quotepath=false diff --no-index --no-ext-diff --no-textconv --color=never -- $taskFrom $taskTo)
  $taskDiffExit=$LASTEXITCODE
  $taskDiffOut | Set-Content -LiteralPath (Join-Path $taskDiffDir $taskDiffName) -Encoding utf8
  [pscustomobject]@{from=$taskFromRel;to=$taskToRel;diff=('diffs/'+$taskDiffName);exit_code=$taskDiffExit;changed=($taskDiffExit -eq 1)}
 }
})
$taskDiffIndex | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $taskDiffDir 'index.json') -Encoding utf8

$taskSnapshotChecks=@(foreach($taskStage in (Get-ChildItem -LiteralPath (Join-Path $taskArchive 'stages') -Directory)){
 foreach($taskFile in (Get-ChildItem -LiteralPath $taskStage.FullName -Recurse -File)){
  $taskRel=[IO.Path]::GetRelativePath($taskStage.FullName,$taskFile.FullName).Replace('\','/')
  $taskLive=Join-Path $taskRoot $taskRel
  if(Test-Path -LiteralPath $taskLive -PathType Leaf){
   [pscustomobject]@{snapshot=[IO.Path]::GetRelativePath($taskArchive,$taskFile.FullName).Replace('\','/');original=$taskRel;matches=((Get-FileHash -LiteralPath $taskFile.FullName).Hash -eq (Get-FileHash -LiteralPath $taskLive).Hash)}
  }
 }
})
$taskSnapshotChecks | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $taskArchive 'environment/stage-snapshot-integrity.json') -Encoding utf8

$taskBaseline=Get-Content -LiteralPath (Join-Path $taskArchive 'environment/existing-files-baseline.json') -Raw | ConvertFrom-Json
$taskEndExisting=@(foreach($taskItem in $taskBaseline){
 $taskActual=(Get-FileHash -LiteralPath (Join-Path $taskRoot $taskItem.path) -Algorithm SHA256).Hash.ToLower()
 [pscustomobject]@{path=$taskItem.path;before=$taskItem.sha256;after=$taskActual;unchanged=($taskItem.sha256 -eq $taskActual)}
})
$taskEndExisting | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $taskArchive 'environment/existing-files-end-comparison.json') -Encoding utf8
$taskFingerprint=Get-Content -LiteralPath (Join-Path $taskArchive 'environment/framework-fingerprint-check.json') -Raw | ConvertFrom-Json
$taskEndFingerprint=@(foreach($taskItem in $taskFingerprint){
 $taskActual=(Get-FileHash -LiteralPath (Join-Path $taskRoot $taskItem.path) -Algorithm SHA256).Hash.ToLower()
 [pscustomobject]@{path=$taskItem.path;expected=$taskItem.expected;actual=$taskActual;matches=($taskItem.expected -eq $taskActual)}
})
$taskEndFingerprint | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $taskArchive 'environment/framework-fingerprint-end.json') -Encoding utf8

$taskHead=(& git -c "safe.directory=$taskRoot" rev-parse HEAD)
$taskHead | Set-Content -LiteralPath (Join-Path $taskArchive 'environment/git-head-end.txt') -Encoding utf8
$taskGit=@(& git -c "safe.directory=$taskRoot" -c core.quotepath=false status --porcelain=v1 --untracked-files=all)
$taskGit | Set-Content -LiteralPath (Join-Path $taskArchive 'environment/git-status-end.txt') -Encoding utf8
$taskUnexpected=@(foreach($taskLine in $taskGit){
 $taskPath=$taskLine.Substring(3)
 if($taskPath -notin @('AGENTS.md','FRAMEWORK.md','MODEL_ENTRY.md','framework-manifest.json') -and -not ($taskPath -like 'experiments/preparation-20261012-bc-loop-01/*') -and -not (@($taskFolders | Where-Object {$taskPath.StartsWith($_+'/')}).Count -gt 0)){$taskPath}
})
$taskSummary=[pscustomobject]@{
 regular_files=$taskMan.Count;active_files=$taskCurrent.Count;diff_pairs=$taskDiffIndex.Count;diff_failures=@($taskDiffIndex|Where-Object {$_.exit_code -gt 1}).Count;
 snapshots_compared=$taskSnapshotChecks.Count;snapshot_mismatches=@($taskSnapshotChecks|Where-Object {-not $_.matches}).Count;
 framework_entries=$taskEndFingerprint.Count;framework_mismatches=@($taskEndFingerprint|Where-Object {-not $_.matches}).Count;
 existing_files_checked=$taskEndExisting.Count;existing_files_changed=@($taskEndExisting|Where-Object {-not $_.unchanged}).Count;
 head=$taskHead;unexpected_paths=$taskUnexpected
}
$taskSummary | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $taskArchive 'environment/final-verification.json') -Encoding utf8
$taskSummary | ConvertTo-Json -Depth 8

$taskArchive='experiments/preparation-20261012-bc-loop-01'
$taskDiffIndex=Get-Content -LiteralPath (Join-Path $taskArchive 'diffs/index.json') -Raw | ConvertFrom-Json
foreach($taskItem in $taskDiffIndex){
 if($taskItem.from -like 'questions/*' -or $taskItem.from -like 'materials/*'){
  [pscustomobject]@{from=$taskItem.from;to=$taskItem.to;changes=@(Get-Content -LiteralPath (Join-Path $taskArchive $taskItem.diff) | Where-Object {($_ -match '^[+-]') -and ($_ -notmatch '^[+-]{3}')})} | ConvertTo-Json -Depth 5
 }
}
